import{z as i,x as o,o as r,c as h,q as B,j as n,D as m,d as e,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"gamma-theta 权衡","description":"","frontmatter":{"title":"gamma-theta 权衡","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gamma-theta-tradeoff.md","filePath":"quant/gamma-theta-tradeoff.md","lastUpdated":1791413859000}'),d={name:"quant/gamma-theta-tradeoff.md"};function A(p,a,D,g,f,T){const E=o("Mermaid");return r(),h("div",null,[a[2]||(a[2]=B('<h1 id="gamma-theta-权衡" tabindex="-1">gamma-theta 权衡 <a class="header-anchor" href="#gamma-theta-权衡" aria-label="Permalink to &quot;gamma-theta 权衡&quot;">​</a></h1><div class="epigraph"><p>持有期权的 Theta 是你为 Gamma 付的租金；已实现波动若高于隐含，租金才赚得回来。</p><footer>—— 对照 Taleb 对期权动态对冲的叙述；BSM 方程里 $\\Theta+\\tfrac12\\sigma^2 S^2\\Gamma$ 与利率项的平衡</footer></div><p><a href="/quant/iv-surface-dynamics">上一课</a>把曲面因子写进情景。本课回到单日 PnL 的会计：<strong>Gamma 赚已实现、Theta 付隐含。</strong> 主干 <a href="/quant/discrete-hedge-error">离散对冲误差</a> 与 <a href="/quant/greeks-hedge">Greeks 对冲</a> 已写复制误差。缺口是把 BSM 的瞬时恒等式当成交易员的日 PnL 分解，并写清微笑与跳如何让恒等式破损。后课模型风险把「隐含 vs 已实现」升成模型选择。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Delta 对冲后，BSM 世界里瞬时</p> \\[\\mathrm{d}V-\\Delta\\mathrm{d}S \\approx \\Theta\\mathrm{d}t+\\tfrac12\\Gamma(\\mathrm{d}S)^2+\\cdots \\]<p>而定价时 \\(\\Theta+\\tfrac12\\sigma_{\\mathrm{imp}}^2 S^2\\Gamma\\approx r(V-\\Delta S)\\)（略去股息）。</p><p><span class="marginnote">租金的数字实例：现货 100、隐含年化 20%、平值看涨 \\(\\Gamma\\approx 0.06\\)，日租金约 \\(\\tfrac12 S^2\\Gamma\\cdot\\sigma^2/252\\approx 0.05\\) 元/股——持有不动每天扣这么多，周末连扣三天。Gamma 赚回的必须超过这条流水：这就是「已实现要高于隐含」的具体含义。</span>于是超额 PnL 大约是 \\(\\tfrac12 S^2\\Gamma\\bigl((\\mathrm{d}S/S)^2-\\sigma_{\\mathrm{imp}}^2\\mathrm{d}t\\bigr)\\)。多 Gamma 的人在已实现方差高于隐含方差时赚钱。问题是：这是<strong>对冲后的方差互换型暴露</strong>，不是「方向对了」；微笑下每个 \\(K\\) 的 \\(\\sigma_{\\mathrm{imp}}\\) 不同，总 Gamma 加权平均的隐含方差才是你付的租金。把 ATM 隐波当所有腿的租金，会在偏斜产品上把账做平。</p><p>Theta 还含利率与时间衰减的会计项。周末、节假日的日历 Theta 与交易日已实现不对齐，见 <a href="/quant/calendar-overnight">日历与隔夜</a>。</p><h3 id="跳让-gamma-租金变成数字风险" tabindex="-1">跳让 Gamma 租金变成数字风险 <a class="header-anchor" href="#跳让-gamma-租金变成数字风险" aria-label="Permalink to &quot;跳让 Gamma 租金变成数字风险&quot;">​</a></h3><p>连续路径下 \\((\\mathrm{d}S)^2\\) 与 \\(\\sigma^2\\mathrm{d}t\\) 比。跳来时 \\((\\Delta S)^2\\) 很大，Gamma 近似失效，PnL 由跳跃大小与期权凸性的离散差决定。卖方若靠收 Theta 过日子，是在卖跳。这与 <a href="/quant/variance-swap-vix">方差互换</a> 的跳修正是同一件事，只是名义换成了你簿上的 \\(\\Gamma(K)\\) 分布。</p><p><span class="marginnote">Gamma 的符号在障碍附近可以与香草相反。敲出前多 Gamma、敲出后归零，Theta 仍在收，权衡在壁附近不是平稳的日租金。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>日终分解：Delta PnL、Gamma/已实现、Theta/隐含、Vega/曲面变化、残余（高阶、跳、费用）。已实现用与对冲频率一致的采样，不要用日度平方去解释五分钟对冲的簿。对冲频率提高，已实现更接近二次变差，也更吃微观结构噪声，见 <a href="/quant/rv-noise">已实现波动与噪声</a>。</p><p>限额：用 \\(\\tfrac12 S^2\\Gamma\\) 当方差名义，对比隐含方差与预测 RV。</p><p><span class="marginnote">术语翻译：「把期权簿翻译成方差互换语言」指：每张期权的 \\(\\tfrac12 S^2\\Gamma\\) 就是它的方差名义——相当于把不同币种按汇率折成同一种货币。折算后，整个期权簿变成一张「方差头寸表」，才能与 RV 预测模型直接对表、按统一的方差限额管理。</span></p>',16)),(r(),n(s,null,{default:m(()=>[l(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20BK%5B%22%E6%9C%9F%E6%9D%83%E7%B0%BF%EF%BC%9A%E5%90%84%E8%85%BF%E5%B8%8C%E8%85%8A%E5%AD%97%E6%AF%8D%22%5D%20--%3E%20D1%5B%22%E6%A1%B6%E4%B8%80%EF%BC%9ADelta%20PnL%EF%BC%88%E5%BA%94%E8%BF%91%E9%9B%B6%EF%BC%89%22%5D%0A%20%20BK%20--%3E%20D2%5B%22%E6%A1%B6%E4%BA%8C%EF%BC%9AGamma%20%E8%B5%9A%E5%B7%B2%E5%AE%9E%E7%8E%B0%22%5D%0A%20%20BK%20--%3E%20D3%5B%22%E6%A1%B6%E4%B8%89%EF%BC%9ATheta%20%E4%BB%98%E9%9A%90%E5%90%AB%22%5D%0A%20%20BK%20--%3E%20D4%5B%22%E6%A1%B6%E5%9B%9B%EF%BC%9AVega%20%E4%BB%98%E6%9B%B2%E9%9D%A2%E5%8F%98%E5%8A%A8%22%5D%0A%20%20BK%20--%3E%20D5%5B%22%E6%A1%B6%E4%BA%94%EF%BC%9A%E6%AE%8B%E4%BD%99%EF%BC%88%E8%B7%B3%E3%80%81%E8%B4%B9%E7%94%A8%E3%80%81%E9%AB%98%E9%98%B6%EF%BC%89%22%5D%0A%20%20D2%20--%3E%20LIM%5B%22%E9%99%90%E9%A2%9D%EF%BC%9A%C2%BDS%C2%B2%CE%93%20%E5%BD%93%E6%96%B9%E5%B7%AE%E5%90%8D%E4%B9%89%22%5D%0A%20%20D3%20--%3E%20LIM%0A%20%20LIM%20--%3E%20RV%5B%22%E4%B8%8E%20HAR%20%E7%B1%BB%20RV%20%E9%A2%84%E6%B5%8B%E5%AF%B9%E8%A1%A8%22%5D%0A"})]),fallback:m(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[e("这是把期权簿翻译成方差互换语言，便于和 "),t("a",{href:"/quant/har-rv"},"HAR"),e(" 一类预测对表。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"你买凸性，就得付时间。市场通过隐波收这份租金。若你的对冲把方向拿走，剩下的赌注是二次变差对隐含方差。曲面因子动时，Vega PnL 会盖过 Gamma-Theta；那不是权衡失效，是你还暴露在 Cont–da Fonseca 的水平上。先把 Vega 对冲到桶限额内，Gamma-Theta 才读得出来。",-1)),(r(),n(s,null,{default:m(()=>[l(E,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20DH%5B%22Delta%20%E5%AF%B9%E5%86%B2%E5%90%8E%22%5D%20--%3E%20GT%5B%22Gamma%20%E4%B9%98%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%96%B9%E5%B7%AE%22%5D%0A%20%20DH%20--%3E%20Th%5B%22Theta%20%E4%BB%98%E9%9A%90%E5%90%AB%E6%96%B9%E5%B7%AE%22%5D%0A%20%20GT%20--%3E%20Edge%5B%22%E5%B7%AE%E6%98%AF%E6%96%B9%E5%B7%AE%E4%BA%92%E6%8D%A2%E5%9E%8B%20PnL%22%5D%0A%20%20Th%20--%3E%20Edge%0A%20%20Jump%5B%22%E8%B7%B3%22%5D%20--%3E%20Break%5B%22Gamma%20%E8%BF%91%E4%BC%BC%E7%A0%B4%E8%A3%82%22%5D%0A"})]),fallback:m(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>离散对冲、买卖价差、隔夜缺口使恒等式只是分解框架，不是保证。</p><p><span class="marginnote">常见误区：看到「今天 Gamma 赚了」就以为是已实现超过隐含。实际上 Delta 没对干净，方向盈亏会整桶混进 Gamma 桶；曲面一动，Vega PnL 又能盖过 Gamma-Theta。所以读这组数字前先查两件事：Delta 桶是否近零、Vega 桶是否在限额内——否则你读到的「权衡」是别的风险的投影。</span>美式提前行权、融资与股票借券进入 carry，不在纯 \\(\\Gamma\\)–\\(\\Theta\\) 里。结构产品的「Theta」往往含障碍时间流逝，符号与香草相反，不要用同一句「卖方收租」概括 autocallable。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Delta 对冲后，多 Gamma 赚已实现减隐含；租金应按簿上 \\(\\Gamma(K)\\) 加权的隐波来算。</li><li>跳与障碍让瞬时恒等式破裂。</li><li>先把 Vega 桶对冲掉，再读 Gamma-Theta，否则被曲面因子淹没。</li><li>出处：BSM 方程的 \\(\\Theta\\)–\\(\\Gamma\\) 平衡；Taleb, <em>Dynamic Hedging</em>；跳与方差复制见 Carr–Madan。</li></ul>',5))])}const G=i(d,[["render",A]]);export{u as __pageData,G as default};
